package main

import (
	"bufio"
	"fmt"
	"math/big"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type EmpRec struct { // 01 EMP-REC, 17 bytes
	ErId    string          // PIC X(5) @0 len=5
	ErDept  string          // PIC X(3) @5 len=3
	ErHours decimal.Decimal // PIC 9(3)V9 @8 len=4
	ErRate  decimal.Decimal // PIC 9(3)V99 @12 len=5
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsFirstFlag string = "Y" // PIC X len=1 = "Y"
var WsPrevDept string = "   " // PIC X(3) len=3 = SPACES
var WsRegHours decimal.Decimal = decimal.NewFromInt(0) // PIC 9(3)V9 len=4 = 0
var WsOtHours decimal.Decimal = decimal.NewFromInt(0)  // PIC 9(3)V9 len=4 = 0
var WsGross decimal.Decimal = decimal.NewFromInt(0)    // PIC 9(7)V99 len=9 = 0
var WsDeptTotal decimal.Decimal = decimal.NewFromInt(0) // PIC 9(9)V99 len=11 = 0
var WsDeptCount int64 = 0                               // PIC 9(3) len=3 = 0
var WsGrandTotal decimal.Decimal = decimal.NewFromInt(0) // PIC 9(11)V99 len=13 = 0
var WsGrandCount int64 = 0                                // PIC 9(5) len=5 = 0
var WsHoursEd string                                      // PIC ZZ9.9 len=5
var WsRateEd string                                       // PIC ZZ9.99 len=6
var WsGrossEd string                                      // PIC Z,ZZZ,ZZ9.99 len=12
var WsDeptEd string                                       // PIC ZZZ,ZZZ,ZZ9.99 len=14
var WsGrandEd string                                      // PIC ZZ,ZZZ,ZZZ,ZZ9.99 len=17

var empFile *os.File
var empScanner *bufio.Scanner
var EmpRecGlobal EmpRec

func isInputDone() bool { return WsEofFlag == "Y" }
func isFirstRecord() bool { return WsFirstFlag == "Y" }

func pow10(n int) decimal.Decimal {
	return decimal.NewFromBigInt(new(big.Int).Exp(big.NewInt(10), big.NewInt(int64(n)), nil), 0)
}

// store numeric into PIC 9(intDigits)V(scale) keeping low-order digits, truncating toward zero to scale
func storeDecimalTrunc(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// Truncate toward zero to scale
	t := v.Truncate(scale)
	// keep low-order digits: modulo 10^(intDigits+scale) on scaled integer
	modExp := intDigits + int(scale)
	mod := pow10(modExp) // 10^(intDigits+scale)
	scaled := t.Shift(scale) // t * 10^scale

	// scaled is integer (maybe negative)
	// need trunc towards zero already done, now do modulo keeping sign
	sign := 1
	if scaled.Sign() < 0 {
		sign = -1
		scaled = scaled.Abs()
	}
	// scaled mod mod
	// Use DivMod with decimal? Use big int for exact
	// Convert scaled to integer via BigInt
	// scaled is decimal with exponent 0 (since we shifted)
	bi := scaled.BigInt() // truncates
	// bi.Mod(bi, mod.BigInt()) where mod.BigInt()
	modBi := mod.BigInt()
	bi.Mod(bi, modBi)
	res := decimal.NewFromBigInt(bi, -int32(scale))
	if sign < 0 {
		res = res.Neg()
	}
	return res
}

func storeInt64Trunc(v int64, digits int) int64 {
	if digits <= 0 {
		return 0
	}
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	// keep low-order digits, handle negative
	sign := int64(1)
	if v < 0 {
		sign = -1
		v = -v
	}
	v = v % mod
	return v * sign
}

// numeric-edited formatting
func formatEdited(v decimal.Decimal, pic string) string {
	// count digits before and after dot
	dotIdx := strings.Index(pic, ".")
	var intPicPart, fracPicPart string
	if dotIdx >= 0 {
		intPicPart = pic[:dotIdx]
		fracPicPart = pic[dotIdx+1:]
	} else {
		intPicPart = pic
		fracPicPart = ""
	}
	intCap := 0
	for _, c := range intPicPart {
		if c == 'Z' || c == '9' {
			intCap++
		}
	}
	fracCap := 0
	for _, c := range fracPicPart {
		if c == 'Z' || c == '9' {
			fracCap++
		}
	}
	scale := int32(fracCap)

	// Truncate (not round) to scale for MOVE semantics; for our values exact
	// Use Truncate to mimic without ROUNDED
	vt := v.Truncate(scale)

	abs := vt.Abs()
	// get string fixed with truncation: we already truncated, so StringFixed will not round further
	// Build frac and int strings
	var intStr, fracStr string
	if fracCap > 0 {
		s := abs.StringFixed(scale) // e.g. "0.00" or "123.45"
		parts := strings.SplitN(s, ".", 2)
		intStr = parts[0]
		if len(parts) > 1 {
			fracStr = parts[1]
		} else {
			fracStr = strings.Repeat("0", fracCap)
		}
		// ensure fracStr length = fracCap
		if len(fracStr) < fracCap {
			fracStr = fracStr + strings.Repeat("0", fracCap-len(fracStr))
		} else if len(fracStr) > fracCap {
			fracStr = fracStr[:fracCap]
		}
	} else {
		s := abs.StringFixed(0)
		// s may contain decimal point? no
		// For integer pics, StringFixed(0) returns integer
		// Remove sign if any (abs already)
		if dot := strings.Index(s, "."); dot >= 0 {
			s = s[:dot]
		}
		intStr = s
		fracStr = ""
	}
	// drop high-order digits if needed
	if len(intStr) > intCap {
		intStr = intStr[len(intStr)-intCap:]
	}
	// pad intStr to intCap with leading zeros
	if len(intStr) < intCap {
		intStr = strings.Repeat("0", intCap-len(intStr)) + intStr
	}
	// Now map pic to output
	out := make([]byte, len(pic))
	// For suppression we need to know integer digit values in order
	// We'll iterate over pic indices, with pointer idx for integer digits
	intDigitIdx := 0
	// Determine suppression: we need to know for each integer placeholder whether we have seen non-zero
	// We'll do a forward pass to decide suppressing flag at each position
	// Simpler: iterate left to right maintaining suppressing boolean
	suppressing := true
	// To know if suppressing should end, we look at digit values ahead? Actually suppression ends when we encounter a non-zero digit
	// That's determined as we go. For Z with '0' we keep suppressing, for non-zero we end.
	// For '9' we end regardless after printing (since 9 prints zero)
	for i, ch := range pic {
		if ch == '.' {
			out[i] = '.'
			suppressing = false // after decimal point, commas not relevant
			continue
		}
		if ch == ',' {
			if suppressing {
				// check if all remaining integer digits up to end are zero? Actually comma suppression stays until first non-zero digit appears
				// We can decide based on suppressing flag before processing this comma: if still suppressing, comma is space
				// But suppressing flag should have been updated based on previous digits only.
				// So just check suppressing
				out[i] = ' '
			} else {
				out[i] = ','
			}
			continue
		}
		if ch == 'Z' || ch == '9' {
			// This placeholder corresponds to a digit
			var digit byte
			if intDigitIdx < len(intStr) {
				// This is integer part (before dot)
				digit = intStr[intDigitIdx]
			} else {
				// This must be fractional part after dot - we need separate index
				// But our intDigitIdx currently covers integer digits only; for fraction we need fracIdx
				// So we need two phases: before dot and after dot.
				// To handle uniformly, split processing: we will process int part and frac part separately by scanning pic
				// For now fallback
				digit = '0'
			}
			// Determine suppressing transition: only for integer part and only while suppressing
			// We are in integer part if i < dotIdx (or dotIdx==-1 means all integer)
			isIntPart := false
			if dotIdx < 0 {
				isIntPart = true
			} else {
				isIntPart = i < dotIdx
			}
			if isIntPart {
				if digit != '0' {
					suppressing = false
				}
				if ch == '9' {
					// 9 always prints digit; also ends suppression after this? For trailing zeros after, suppression should be off
					// If we are at a 9 and digit is zero but earlier digits were zero, we still print zero. So we should turn off suppression after printing 9
					// But for logic of commas before, the 9 is at end so not relevant. We'll turn off to ensure later commas (none) behave.
					// However for pics where 9 is at end, we should ensure that zero is printed even if suppressing.
					if suppressing {
						// this is the first non-suppressed position due to 9
						// after printing it, suppression ends
						// but digit is zero, we still print zero
						out[i] = digit
						suppressing = false
					} else {
						out[i] = digit
					}
				} else { // Z
					if suppressing {
						// leading zero -> space (if digit zero)
						// if digit non-zero, suppression already turned off above, so print digit
						if digit == '0' {
							out[i] = ' '
						} else {
							out[i] = digit
						}
					} else {
						out[i] = digit
					}
				}
				intDigitIdx++
			} else {
				// fractional part: no suppression, just print digit from fracStr
				// Need frac index
				// Compute frac index based on position among fractional placeholders
				// We'll handle fractional part in second pass; for now placeholder
				out[i] = '?'
			}
		} else {
			out[i] = byte(ch)
		}
	}
	// Now fill fractional digits correctly (they were '?' above)
	if fracCap > 0 && dotIdx >= 0 {
		fracIdx := 0
		for i, ch := range pic {
			if i <= dotIdx {
				continue
			}
			if ch == 'Z' || ch == '9' {
				if fracIdx < len(fracStr) {
					out[i] = fracStr[fracIdx]
				} else {
					out[i] = '0'
				}
				fracIdx++
			}
		}
	}
	return string(out)
}

func formatIntUnedited(v int64, width int) string {
	// keep low-order digits
	mod := int64(1)
	for i := 0; i < width; i++ {
		mod *= 10
	}
	abs := v
	if abs < 0 {
		abs = -abs
	}
	abs = abs % mod
	// zero pad
	s := fmt.Sprintf("%0*d", width, abs)
	if v < 0 {
		// COBOL would show sign? Not needed
	}
	return s
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func parseDecimalDigits(s string, scale int32) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		s = "0"
	}
	// s contains digits only (maybe spaces removed) - COBOL numeric field stores digits
	// Keep only digits
	digits := ""
	for _, c := range s {
		if c >= '0' && c <= '9' {
			digits += string(c)
		}
	}
	if digits == "" {
		digits = "0"
	}
	bi, _ := new(big.Int).SetString(digits, 10)
	if bi == nil {
		bi = big.NewInt(0)
	}
	return decimal.NewFromBigInt(bi, -scale)
}

func main() {
	// OPEN INPUT EMP-FILE
	var err error
	empFile, err = os.Open("input.dat")
	if err != nil {
		// if file doesn't exist, treat as empty (COBOL would error, but handle)
		empFile = nil
		empScanner = bufio.NewScanner(strings.NewReader(""))
	} else {
		empScanner = bufio.NewScanner(empFile)
	}
	// In COBOL LINE SEQUENTIAL, lines are records
	MAIN_PARA()
	if empFile != nil {
		empFile.Close()
	}
}

func MAIN_PARA() {
	// OPEN already done
	READ_PARA()
	for !isInputDone() {
		PROCESS_PARA()
	}
	if !isFirstRecord() {
		DEPT_BREAK_PARA()
	}
	// CLOSE EMP-FILE handled in main
	GRAND_PARA()
}

func READ_PARA() {
	if empScanner == nil || !empScanner.Scan() {
		WsEofFlag = "Y"
		return
	}
	line := empScanner.Text()
	// Pad with spaces on right to record length 17
	if len(line) < 17 {
		line = line + strings.Repeat(" ", 17-len(line))
	}
	if len(line) > 17 {
		line = line[:17]
	}
	EmpRecGlobal.ErId = line[0:5]
	EmpRecGlobal.ErDept = line[5:8]
	EmpRecGlobal.ErHours = parseDecimalDigits(line[8:12], 1)
	EmpRecGlobal.ErRate = parseDecimalDigits(line[12:17], 2)
}

func PROCESS_PARA() {
	if isFirstRecord() {
		WsPrevDept = EmpRecGlobal.ErDept
		WsFirstFlag = "N"
	} else {
		if EmpRecGlobal.ErDept != WsPrevDept {
			DEPT_BREAK_PARA()
			WsPrevDept = EmpRecGlobal.ErDept
		}
	}
	PAY_PARA()
	READ_PARA()
}

func PAY_PARA() {
	if EmpRecGlobal.ErHours.GreaterThan(decimal.NewFromInt(40)) {
		// MOVE 40 TO WS-REG-HOURS
		WsRegHours = decimal.NewFromInt(40)
		// COMPUTE WS-OT-HOURS = ER-HOURS - 40
		diff := EmpRecGlobal.ErHours.Sub(decimal.NewFromInt(40))
		WsOtHours = storeDecimalTrunc(diff, 3, 1)
	} else {
		WsRegHours = storeDecimalTrunc(EmpRecGlobal.ErHours, 3, 1)
		WsOtHours = decimal.NewFromInt(0)
	}
	// COMPUTE WS-GROSS ROUNDED = WS-REG-HOURS * ER-RATE + WS-OT-HOURS * ER-RATE * 1.5
	onePointFive := decimal.NewFromFloat(1.5)
	// decimal.NewFromFloat may introduce binary float issues, use New(15, -1)
	onePointFive = decimal.New(15, -1)
	computed := WsRegHours.Mul(EmpRecGlobal.ErRate).Add(WsOtHours.Mul(EmpRecGlobal.ErRate).Mul(onePointFive))
	rounded := computed.Round(2)
	WsGross = storeDecimalTrunc(rounded, 7, 2)

	WsDeptTotal = WsDeptTotal.Add(WsGross)
	WsDeptTotal = storeDecimalTrunc(WsDeptTotal, 9, 2)
	WsDeptCount = WsDeptCount + 1
	WsDeptCount = storeInt64Trunc(WsDeptCount, 3)
	WsGrandTotal = WsGrandTotal.Add(WsGross)
	WsGrandTotal = storeDecimalTrunc(WsGrandTotal, 11, 2)
	WsGrandCount = WsGrandCount + 1
	WsGrandCount = storeInt64Trunc(WsGrandCount, 5)

	WsHoursEd = formatEdited(storeDecimalTrunc(EmpRecGlobal.ErHours, 3, 1), "ZZ9.9")
	WsRateEd = formatEdited(storeDecimalTrunc(EmpRecGlobal.ErRate, 3, 2), "ZZ9.99")
	WsGrossEd = formatEdited(WsGross, "Z,ZZZ,ZZ9.99")
	// DISPLAY ER-ID " " ER-DEPT " " WS-HOURS-ED " " WS-RATE-ED " " WS-GROSS-ED
	// PIC X fields are exactly n characters, padded spaces? They already are length.
	fmt.Printf("%s %s %s %s %s\n", padRight(EmpRecGlobal.ErId, 5), padRight(EmpRecGlobal.ErDept, 3), WsHoursEd, WsRateEd, WsGrossEd)
}

func DEPT_BREAK_PARA() {
	WsDeptEd = formatEdited(WsDeptTotal, "ZZZ,ZZZ,ZZ9.99")
	// DISPLAY "  DEPT " WS-PREV-DEPT " EMPLOYEES: " WS-DEPT-COUNT " TOTAL: " WS-DEPT-ED
	countStr := formatIntUnedited(WsDeptCount, 3)
	fmt.Printf("  DEPT %s EMPLOYEES: %s TOTAL: %s\n", padRight(WsPrevDept, 3), countStr, WsDeptEd)
	WsDeptTotal = decimal.NewFromInt(0)
	WsDeptCount = 0
}

func GRAND_PARA() {
	WsGrandEd = formatEdited(WsGrandTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	countStr := formatIntUnedited(WsGrandCount, 5)
	fmt.Printf("GRAND TOTAL (%s): %s\n", countStr, WsGrandEd)
}
